func TestGoldenDump(t *testing.T) {
	p := func(id, subj, act, scope, eff string, rec bool, res string) Policy {
		return Policy{ID: id, Subject: subj, Action: act, Scope: scope, Effect: Effect(eff), Recursive: rec, ResourceID: res}
	}
	ff := string([]byte{0xff})
	fe := string([]byte{0xfe})
	fffd := "a�b"
	cases := [][]AuditRecord{
		{
			// ordinary publish, non-empty, resource-qualified + recursive
			mkRec("acme", 1, AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{
				p("p1", "u1", "read", "org/a", "allow", true, "res/9"),
				p("p2", "u2", "write", "org/b", "deny", false, ""),
			}}),
			// rollback with nil policy list payload
			mkRec("acme", 2, AuditPolicyChange, &PolicyChange{Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true}),
			// raw 0xFF / 0xFE / real U+FFFD distinction, non-nil empty list
			mkRec("acme", 3, AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{
				p("x"+ff, "u", "a"+fe, "org", "allow", false, "r"+fffd),
			}}),
			// published empty set is still a version
			mkRec("acme", 4, AuditPolicyChange, &PolicyChange{Version: 4, Policies: []Policy{}}),
		},
	}
	for i, recs := range cases {
		cp := Checkpoint{Org: "acme", EndSeq: len(recs), Fingerprint: recs[len(recs)-1].Fingerprint}
		b, err := EncodeAuditArchive("acme", recs, cp)
		if err != nil {
			t.Fatal(err)
		}
		fmt.Printf("CASE %d ARCHIVE %s\n", i, base64.StdEncoding.EncodeToString(b))
		for _, r := range recs {
			fmt.Printf("CASE %d FP %d %s\n", i, r.Seq, r.Fingerprint)
		}
	}
}

func mkRec(org string, seq int, kind string, ch *PolicyChange) AuditRecord {
	prev := genesisFingerprint(org)
	r := AuditRecord{Org: org, Seq: seq, Kind: kind, Change: ch, PrevFingerprint: prev}
	r.Fingerprint = fingerprintFor(&r)
	if seq > 1 {
		panic("only seq 1 builds in this helper")
	}
	return r
}
